    } ]
  }, {
    "tStartMs": 574307,
    "dDurationMs": 3653,
    "segs": [ {
      "utf8": "好 那當時就提到說這個歌曲"
    } ]
  }, {
    "tStartMs": 577960,
    "dDurationMs": 1986,
    "segs": [ {
      "utf8": "我還記得你在講解裡面"
    } ]
  }, {
    "tStartMs": 579946,
    "dDurationMs": 2602,
    "segs": [ {

text:
    "utf8": "還特別提到一個士林的慈諴宮"
  } ]
}, {
  "tStartMs": 582548,
  "dDurationMs": 701,
  "segs": [ {
    "utf8": "對"
  } ]
}, {
  "tStartMs": 583249,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "然後有一個對場作"
  } ]
}, {
  "tStartMs": 584350,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "我必須跟大家講"
  } ]
}, {
  "tStartMs": 585351,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "因為我的臉書的朋友"
  } ]
}, {
  "tStartMs": 586652,
  "dDurationMs": 1919,
  "segs": [ {
    "utf8": "很多都是文史工作者"
  } ]
}, {
  "tStartMs": 588571,
  "dDurationMs": 1284,
  "segs": [ {
    "utf8": " 或者解說員"
  } ]
}, {
  "tStartMs": 589855,
  "dDurationMs": 684,
  "segs": [ {
    "utf8": "就有人說 "
  } ]
}, {
  "tStartMs": 590539,
  "dDurationMs": 1118,
  "segs": [ {
    "utf8": "天啊 沈伯洋"
  } ]
}, {
  "tStartMs": 591657,
  "dDurationMs": 2403,
  "segs": [ {
    "utf8": "竟然連慈諴宮都唸對了"
  } ]
}, {
  "tStartMs": 594060,
  "dDurationMs": 1785,
  "segs": [ {
    "utf8": "因為很多人唸成慈「誠」宮"
  } ]
}, {
  "tStartMs": 595845,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "我小時候都唸成慈「誠」宮"
  } ]
}, {
  "tStartMs": 598047,
  "dDurationMs": 1134,
  "segs": [ {
    "utf8": "然後說什麼 "
  } ]
}, {
  "tStartMs": 599181,
  "dDurationMs": 1969,
  "segs": [ {
    "utf8": "哇 要對場作這樣"
  } ]
}, {
  "tStartMs": 601150,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "這個歷史都知道"
  } ]
}, {
  "tStartMs": 602551,
  "dDurationMs": 1168,
  "segs": [ {
    "utf8": "所以說這個 "
  } ]
}, {
  "tStartMs": 603719,
  "dDurationMs": 2036,
  "segs": [ {
    "utf8": "你說這是一個「和而不同」"
  } ]
}, {
  "tStartMs": 605755,
  "dDurationMs": 700,
  "segs": [ {
    "utf8": "對不對"
  } ]
}, {
  "tStartMs": 606455,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "那一座廟可以做到的事情 "
  } ]
}, {
  "tStartMs": 608457,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "一座城市"
  } ]
}, {
  "tStartMs": 609458,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "為什麼感覺好像很難"
  } ]
}, {
  "tStartMs": 611360,
  "dDurationMs": 1885,
  "segs": [ {
    "utf8": "對 因為我覺得歷史的融合"
  } ]
}, {
  "tStartMs": 613245,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "其實很重要 "
  } ]
}, {
  "tStartMs": 614246,
  "dDurationMs": 701,
  "segs": [ {
    "utf8": "就是說"
  } ]
}, {
  "tStartMs": 614947,
  "dDurationMs": 1018,
  "segs": [ {
    "utf8": "我覺得歷史 "
  } ]
}, {
  "tStartMs": 615965,
  "dDurationMs": 2085,
  "segs": [ {
    "utf8": "一定有一些對立"
  } ]
}, {
  "tStartMs": 618050,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "然後對立跟競爭"
  } ]
}, {
  "tStartMs": 619552,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "然後有時候甚至"
  } ]
}, {
  "tStartMs": 620453,
  "dDurationMs": 1701,
  "segs": [ {
    "utf8": "就像以前漳泉械鬥一樣"
  } ]
}, {
  "tStartMs": 622154,
  "dDurationMs": 2203,
  "segs": [ {
    "utf8": "這是會出人命的事情"
  } ]
}, {
  "tStartMs": 624357,
  "dDurationMs": 2485,
  "segs": [ {
    "utf8": "然後我們也經歷過二二八"
  } ]
}, {
  "tStartMs": 626842,
  "dDurationMs": 1519,
  "segs": [ {
    "utf8": " 經歷過白色恐怖"
  } ]
}, {
  "tStartMs": 628361,
  "dDurationMs": 1985,
  "segs": [ {
    "utf8": "這些其實都是我們的歷史"
  } ]
}, {
  "tStartMs": 630346,
  "dDurationMs": 1601,
  "segs": [ {
    "utf8": "然後我們也流過血"
  } ]
}, {
  "tStartMs": 631947,
  "dDurationMs": 2703,
  "segs": [ {
    "utf8": "但是後來我們在這個爭執的過程當中"
  } ]
}, {
  "tStartMs": 634650,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "因為爭執就是"
  } ]
}, {
  "tStartMs": 635551,
  "dDurationMs": 2402,
  "segs": [ {
    "utf8": "那個爭執的本質還是存在"
  } ]
}, {
  "tStartMs": 637953,
  "dDurationMs": 1652,
  "segs": [ {
    "utf8": "但是已經變成是 "
  } ]
}, {
  "tStartMs": 639605,
  "dDurationMs": 1852,
  "segs": [ {
    "utf8": "大家遵守民主的制度"
  } ]
}, {
  "tStartMs": 641457,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "我覺得走到這一條路是不容易"
  } ]
}, {
  "tStartMs": 643559,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "所以我之前就一直覺得說"
  } ]
}, {
  "tStartMs": 645161,
  "dDurationMs": 1284,
  "segs": [ {
    "utf8": "台北的文化徑有一條"
  } ]
}, {
  "tStartMs": 646445,
  "dDurationMs": 2403,
  "segs": [ {
    "utf8": "一定要從淡水河這樣沿著一路往上"
  } ]
}, {
  "tStartMs": 648848,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "因為那就是我們打架的歷史 "
  } ]
}, {
  "tStartMs": 650750,
  "dDurationMs": 1651,
  "segs": [ {
    "utf8": "就是一路打"
  } ]
}, {
  "tStartMs": 652401,
  "dDurationMs": 1702,
  "segs": [ {
    "utf8": "最南你從馬場町開始都可以"
  } ]
}, {
  "tStartMs": 654103,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "但是漳泉械鬥那邊 "
  } ]
}, {
  "tStartMs": 655504,
  "dDurationMs": 3204,
  "segs": [ {
    "utf8": "從萬華開始打到艋舺"
  } ]
}, {
  "tStartMs": 658708,
  "dDurationMs": 1267,
  "segs": [ {
    "utf8": "然後再打到士林 "
  } ]
}, {
  "tStartMs": 659975,
  "dDurationMs": 1235,
  "segs": [ {
    "utf8": "打到芝山巖"
  } ]
}, {
  "tStartMs": 661210,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "所以我那時候就覺得"
  } ]
}, {
  "tStartMs": 662211,
  "dDurationMs": 1468,
  "segs": [ {
    "utf8": "因為慈諴宮就在士林 "
  } ]
}, {
  "tStartMs": 663679,
  "dDurationMs": 1018,
  "segs": [ {
    "utf8": "它已經是屬於"
  } ]
}, {
  "tStartMs": 664697,
  "dDurationMs": 2402,
  "segs": [ {
    "utf8": "那時候的爭執的尾端"
  } ]
}, {
  "tStartMs": 667099,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "所以那個時候慈諴宮的意義"
  } ]
}, {
  "tStartMs": 669201,
  "dDurationMs": 1302,
  "segs": [ {
    "utf8": "我就覺得特別的重大"
  } ]
}, {
  "tStartMs": 670503,
  "dDurationMs": 967,
  "segs": [ {
    "utf8": "因為它就是說 "
  } ]
